<p class="eyebrow">User account</p><h1><?= e($user['first_name'].' '.$user['last_name']) ?></h1><div class="grid two dashboard-split"><section class="card"><h2>Account details</h2><dl class="detail-list"><dt>Reference</dt><dd><?= e($user['uuid']) ?></dd><dt>Email</dt><dd><?= e($user['email']) ?> · <?= !empty($user['email_verified_at'])?'verified':'unverified' ?></dd><dt>Registered</dt><dd><?= e($user['created_at']) ?></dd><dt>Last login</dt><dd><?= e($user['last_login_at']??'Never') ?></dd><dt>2FA</dt><dd><?= !empty($user['two_factor_enabled_at'])?'Enabled':'Not enabled' ?></dd></dl></section><section class="card"><h2>Change investment region</h2><p class="muted">This changes the account’s assigned Country Pack and overrides future GeoIP resolution.</p><form method="post" action="<?= e(route('admin.users.country',['user'=>$user['id']])) ?>" class="form-stack" data-confirm="Confirm the investment region change?"><?= app('csrf')->input() ?><label class="field">Country Pack<select name="country_id"><?php foreach($countries as $country): ?><option value="<?= e($country['id']) ?>"<?= (int)($user['assigned_country_id']??$user['country_id'])===(int)$country['id']?' selected':'' ?>><?= e($country['name']) ?> · <?= e($country['currency_code']) ?></option><?php endforeach; ?></select></label><label class="field">Reason <span class="muted">(optional)</span><textarea name="reason" rows="2"></textarea></label><button class="button" type="submit">Confirm Country Pack</button></form></section></div><section class="card"><h2>Account status</h2><form method="post" action="<?= e(route('admin.users.status',['user'=>$user['id']])) ?>" class="form-stack" data-confirm="Confirm this account status change?"><?= app('csrf')->input() ?><label class="field">Status<select name="account_status"><option value="active"<?= $user['account_status']==='active'?' selected':'' ?>>Active</option><option value="restricted"<?= $user['account_status']==='restricted'?' selected':'' ?>>Restricted</option><option value="suspended"<?= $user['account_status']==='suspended'?' selected':'' ?>>Suspended</option></select></label><label class="field">Reason <textarea name="reason" rows="2"><?= e($user['account_restriction_reason']??'') ?></textarea></label><button class="button button-danger" type="submit">Update status</button></form></section><section class="card"><h2>Recent security events</h2><div class="table-wrap"><table><thead><tr><th>Event</th><th>IP</th><th>Time</th></tr></thead><tbody><?php foreach($events as $event): ?><tr><td><?= e($event['event_type']) ?></td><td><?= e($event['ip_address']??'') ?></td><td><?= e($event['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
